class Cache(ttl, clock):
    def __init__(self, ttl, clock):
        self.ttl = ttl
        self.clock = clock

    def _now(self):
        return self.clock.now()

    def set(self, key, value):
        self[key] = value

    def get(self, key, default=None):
        return self[key] if self[key] is not None else default

